// Hand-written `@angular/router` stub: the shape of a route configuration.

export interface Route {
  path?: string;
  pathMatch?: string;
  component?: unknown;
  loadComponent?: () => unknown;
  loadChildren?: () => unknown;
  children?: Route[];
  redirectTo?: string;
  providers?: unknown[];
  canActivate?: unknown[];
  data?: unknown;
  title?: string;
}

export type Routes = Route[];

export declare const RouterModule: {
  forRoot(routes: Routes): unknown;
  forChild(routes: Routes): unknown;
};

export declare function provideRouter(routes: Routes): unknown;
export declare const RouterLink: unknown;
